import type { CityMap } from "@afterfall/world";
import { deriveSeed } from "@afterfall/shared";
import { growthAt, hash2, inBuilding, inWater, onRoad, type ReclamationField } from "./reclamation";
import type { PropPlacement } from "./props";
import { buildingDecay } from "./buildingBatch";

/** The litter kit, generated by `tools/blender/debris.py`. */
export const LITTER_KINDS = ["litter_rubble", "litter_bags", "litter_tires", "litter_planks", "litter_mattress"] as const;
export type LitterKind = (typeof LITTER_KINDS)[number];

/** Instances at most, all kinds together: about 360 k triangles at the kit's sizes. */
export const LITTER_CAP = 600;
/** Spacing of the scatter grid, in metres. */
const STEP = 3.4;
/** Doors stay clear, as they do for grass and trees. */
const DOOR_CLEAR = 3;
/** How far out a wall is looked for: litter gathers against walls, not in the open. */
const WALL_REACH = 3;
/** Half the footprint of each piece, for keeping off walls and away from street props. */
export const LITTER_RADIUS: Record<LitterKind, number> = {
  litter_rubble: 1.15,
  litter_bags: 1.0,
  litter_tires: 0.9,
  litter_planks: 1.3,
  litter_mattress: 1.25,
};

/**
 * What a wall has piled against it: concrete off the facade above everywhere, bin bags
 * by shops and homes, tyres and timber where there was work, a mattress by a home.
 */
function pickKind(r: number, zone: string | undefined): LitterKind {
  if (zone === "industrial") return r < 0.3 ? "litter_rubble" : r < 0.6 ? "litter_tires" : r < 0.88 ? "litter_planks" : "litter_bags";
  if (zone === "commercial") return r < 0.35 ? "litter_bags" : r < 0.65 ? "litter_rubble" : r < 0.85 ? "litter_planks" : "litter_tires";
  return r < 0.35 ? "litter_rubble" : r < 0.66 ? "litter_bags" : r < 0.75 ? "litter_mattress" : r < 0.89 ? "litter_planks" : "litter_tires";
}

/**
 * Scatters the litter kit at the foot of walls and in the corners of lots, more of it
 * where the reclamation field says the street has been left longest. Never on a
 * carriageway, in a doorway or under a street prop. Cosmetic: no collision, nothing
 * taller than a survivor's knee except the odd bent bar. Deterministic per seed.
 */
export function placeLitter(
  city: CityMap,
  field: ReclamationField,
  avoid: readonly PropPlacement[] = [],
  density = 1,
): Map<LitterKind, PropPlacement[]> {
  const out = new Map<LitterKind, PropPlacement[]>();
  const seed = deriveSeed(city.seed >>> 0, "litter");
  const doors = city.buildings.map((b) => b.entrance);
  const nearest = (x: number, z: number) => {
    let best: { zone?: string; decay: number; d: number } = { decay: 0, d: Infinity };
    for (const b of city.buildings) {
      const dx = Math.max(b.rect.x - x, 0, x - b.rect.x - b.rect.w);
      const dz = Math.max(b.rect.y - z, 0, z - b.rect.y - b.rect.h);
      const d = Math.hypot(dx, dz);
      if (d < best.d) best = { zone: b.zone, decay: buildingDecay(b), d };
    }
    return best;
  };
  const placed: { x: number; z: number; r: number }[] = [];
  let total = 0;
  const cols = Math.ceil(city.width / STEP),
    rows = Math.ceil(city.height / STEP);
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++) {
      const x = (c + 0.15 + hash2(c, r, seed) * 0.7) * STEP;
      const z = (r + 0.15 + hash2(c, r, seed + 1) * 0.7) * STEP;
      // The nearest wall, along the four axes: its direction turns the piece to lie along it.
      let wall = -1;
      let wallDist = Infinity;
      const dirs = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ];
      dirs.forEach(([dx, dz], k) => {
        for (let d = 0.5; d <= WALL_REACH; d += 0.5)
          if (inBuilding(field, x + dx * d, z + dz * d)) {
            if (d < wallDist) {
              wallDist = d;
              wall = k;
            }
            break;
          }
      });
      const g = growthAt(field, x, z);
      const near = nearest(x, z);
      // Against a wall most of the time; out in a lot or a plaza now and then. A wreck
      // sheds its facade: more litter at its feet, and most of it rubble, larger.
      const chance = (wall >= 0 ? 0.5 * (0.6 + 0.8 * near.decay) : 0.04) * (0.55 + 0.9 * g);
      if (hash2(c, r, seed + 2) >= chance * density) continue;
      const wreck = wall >= 0 && near.decay > 0.6 && hash2(c, r, seed + 8) < near.decay;
      const kind = wreck ? "litter_rubble" : pickKind(hash2(c, r, seed + 3), near.zone);
      const radius = LITTER_RADIUS[kind];
      const scale = (1 + hash2(c, r, seed + 4) * 0.35) * (wreck ? 1.3 : 1);
      const reach = radius * scale;
      // Pushed back against the wall, keeping its footprint off the building.
      let px = x,
        pz = z;
      if (wall >= 0) {
        const [dx, dz] = dirs[wall];
        const shift = Math.max(0, wallDist - reach - 0.15);
        px += dx * shift;
        pz += dz * shift;
      }
      if (onRoad(field, px, pz) || inWater(field, px, pz)) continue;
      let blocked = false;
      for (let a = 0; a < 8 && !blocked; a++) {
        const ex = px + Math.cos((a * Math.PI) / 4) * reach,
          ez = pz + Math.sin((a * Math.PI) / 4) * reach;
        if (inBuilding(field, ex, ez) || onRoad(field, ex, ez)) blocked = true;
      }
      if (blocked) continue;
      if (doors.some((d) => Math.hypot(d.x - px, d.y - pz) < DOOR_CLEAR + reach)) continue;
      if (avoid.some((p) => Math.hypot(p.x - px, p.z - pz) < 1.6 * (p.scale ?? 1) + reach)) continue;
      if (placed.some((p) => Math.hypot(p.x - px, p.z - pz) < p.r + reach + 0.4)) continue;
      // Long side along the wall, with a little skew; free pieces lie any way.
      const along = wall < 0 ? hash2(c, r, seed + 5) * Math.PI * 2 : wall < 2 ? Math.PI / 2 : 0;
      const rot = along + (hash2(c, r, seed + 6) - 0.5) * 0.5 + (hash2(c, r, seed + 7) < 0.5 ? Math.PI : 0);
      const list = out.get(kind) ?? [];
      list.push({ x: px, z: pz, rot, scale });
      out.set(kind, list);
      placed.push({ x: px, z: pz, r: reach });
      total++;
    }
  // Over budget, thin evenly: stopping the scan at the cap would leave the far rows bare.
  if (total <= LITTER_CAP) return out;
  const keep = LITTER_CAP / total;
  let i = 0;
  for (const [kind, list] of out)
    out.set(
      kind,
      list.filter(() => hash2(i++, 3, seed) < keep),
    );
  return out;
}
